module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);

    localparam integer H = DATA_W + PARITY_W;

    // ------------------------------------------------------------------
    // Encoder
    // ------------------------------------------------------------------
    always_comb begin : enc_blk
        integer p;
        integer k;
        integer d;
        logic [H-1:0] tmp;
        logic         par;
        tmp = '0;
        d   = 0;
        for (p = 1; p <= H; p = p + 1) begin
            if ((p & (p - 1)) != 0) begin
                tmp[p-1] = enc_data[d];
                d = d + 1;
            end
        end
        for (k = 0; k < PARITY_W; k = k + 1) begin
            par = 1'b0;
            for (p = 1; p <= H; p = p + 1) begin
                if ((((p >> k) & 1) == 1) && ((p & (p - 1)) != 0)) begin
                    par = par ^ tmp[p-1];
                end
            end
            tmp[(1 << k) - 1] = par;
        end
        enc_code = {^tmp, tmp};
    end

    // ------------------------------------------------------------------
    // Decoder
    // ------------------------------------------------------------------
    always_comb begin : dec_blk
        integer p;
        integer k;
        integer d;
        integer syn;
        logic [H-1:0] fixed;
        logic         par;
        logic         odd;
        syn   = 0;
        fixed = dec_code[H-1:0];
        for (k = 0; k < PARITY_W; k = k + 1) begin
            par = 1'b0;
            for (p = 1; p <= H; p = p + 1) begin
                if (((p >> k) & 1) == 1) begin
                    par = par ^ dec_code[p-1];
                end
            end
            if (par) syn = syn | (1 << k);
        end
        odd = ^dec_code;

        corrected     = 1'b0;
        uncorrectable = 1'b0;
        if (!odd) begin
            if (syn != 0) uncorrectable = 1'b1;
        end else begin
            corrected = 1'b1;
            if (syn == 0) begin
                // overall parity bit wrong; no data change
            end else if (syn <= H) begin
                fixed[syn-1] = ~fixed[syn-1];
            end else begin
                corrected     = 1'b0;
                uncorrectable = 1'b1;
            end
        end

        dec_data = '0;
        d = 0;
        for (p = 1; p <= H; p = p + 1) begin
            if ((p & (p - 1)) != 0) begin
                dec_data[d] = fixed[p-1];
                d = d + 1;
            end
        end
    end

endmodule

module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);

    localparam integer H = DATA_W + PARITY_W;

    function automatic logic is_pow2(input integer p);
        is_pow2 = (p > 0) && ((p & (p - 1)) == 0);
    endfunction

    // ---------------- Encoder ----------------
    logic [H-1:0] enc_h;

    always_comb begin
        integer p;
        integer k;
        integer j;
        logic   tmp;
        enc_h = '0;
        j = 0;
        for (p = 1; p <= H; p++) begin
            if (!is_pow2(p)) begin
                enc_h[p-1] = enc_data[j];
                j = j + 1;
            end
        end
        for (k = 0; k < PARITY_W; k++) begin
            tmp = 1'b0;
            for (p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) begin
                    tmp = tmp ^ enc_h[p-1];
                end
            end
            enc_h[(1 << k) - 1] = tmp;
        end
        enc_code = {^enc_h, enc_h};
    end

    // ---------------- Decoder ----------------
    logic [H-1:0]        dec_h;
    logic [H-1:0]        fixed_h;
    logic [PARITY_W-1:0] syn;
    logic                odd;

    always_comb begin
        integer p;
        integer k;
        integer j;
        integer sidx;
        logic   tmp;

        dec_h = dec_code[H-1:0];
        syn   = '0;
        for (k = 0; k < PARITY_W; k++) begin
            tmp = 1'b0;
            for (p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) begin
                    tmp = tmp ^ dec_h[p-1];
                end
            end
            syn[k] = tmp;
        end

        odd = ^dec_code;
        sidx = syn;

        fixed_h       = dec_h;
        corrected     = 1'b0;
        uncorrectable = 1'b0;

        if (odd) begin
            if (sidx == 0) begin
                corrected = 1'b1;
            end else if (sidx <= H) begin
                corrected = 1'b1;
                fixed_h[sidx-1] = ~fixed_h[sidx-1];
            end else begin
                uncorrectable = 1'b1;
            end
        end else begin
            if (sidx != 0) begin
                uncorrectable = 1'b1;
            end
        end

        dec_data = '0;
        j = 0;
        for (p = 1; p <= H; p++) begin
            if (!is_pow2(p)) begin
                dec_data[j] = fixed_h[p-1];
                j = j + 1;
            end
        end
    end

endmodule

module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);

    localparam integer H = DATA_W + PARITY_W;

    // ---------------- Encoder ----------------
    logic [H-1:0] enc_cw;
    integer enc_j;
    integer enc_p;
    integer enc_k;

    always_comb begin
        enc_cw = '0;
        enc_j  = 0;
        // Place data bits in non-power-of-two positions, increasing order
        for (enc_p = 1; enc_p <= H; enc_p = enc_p + 1) begin
            if ((enc_p & (enc_p - 1)) != 0) begin
                enc_cw[enc_p-1] = enc_data[enc_j];
                enc_j = enc_j + 1;
            end
        end
        // Compute check bits (check positions are zero while computing,
        // and a check position 2^k never lies in another group k'!=k)
        for (enc_k = 0; enc_k < PARITY_W; enc_k = enc_k + 1) begin
            for (enc_p = 1; enc_p <= H; enc_p = enc_p + 1) begin
                if (((enc_p >> enc_k) & 1) != 0 && enc_p != (1 << enc_k)) begin
                    enc_cw[(1 << enc_k) - 1] = enc_cw[(1 << enc_k) - 1] ^ enc_cw[enc_p-1];
                end
            end
        end
        enc_code = {^enc_cw, enc_cw};
    end

    // ---------------- Decoder ----------------
    logic [PARITY_W-1:0] dec_syn;
    logic [H-1:0]        dec_corr;
    logic                dec_odd;
    integer              dec_p;
    integer              dec_k;
    integer              dec_j;
    integer              dec_sv;

    always_comb begin
        dec_syn = '0;
        for (dec_p = 1; dec_p <= H; dec_p = dec_p + 1) begin
            for (dec_k = 0; dec_k < PARITY_W; dec_k = dec_k + 1) begin
                if (((dec_p >> dec_k) & 1) != 0)
                    dec_syn[dec_k] = dec_syn[dec_k] ^ dec_code[dec_p-1];
            end
        end
        dec_odd  = ^dec_code;
        dec_corr = dec_code[H-1:0];
        dec_sv   = dec_syn;

        corrected     = 1'b0;
        uncorrectable = 1'b0;

        if (dec_odd) begin
            if (dec_sv == 0) begin
                corrected = 1'b1;
            end else if (dec_sv <= H) begin
                corrected = 1'b1;
                dec_corr[dec_sv-1] = ~dec_corr[dec_sv-1];
            end else begin
                uncorrectable = 1'b1;
            end
        end else if (dec_sv != 0) begin
            uncorrectable = 1'b1;
        end

        // Extract data from noncheck positions in increasing order
        dec_data = '0;
        dec_j    = 0;
        for (dec_p = 1; dec_p <= H; dec_p = dec_p + 1) begin
            if ((dec_p & (dec_p - 1)) != 0) begin
                dec_data[dec_j] = dec_corr[dec_p-1];
                dec_j = dec_j + 1;
            end
        end
    end

endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);

    // Buffer of up to 8 units; index 0 is the oldest unit.
    logic [UNIT_W-1:0] buf_q [0:7];
    logic [UNIT_W-1:0] nxt   [0:7];
    logic [3:0]        cnt_q;
    logic [3:0]        cnt_n;

    logic out_fire;
    logic in_fire;
    int   m;
    int   n;

    always_comb begin
        n = int'(cnt_q);
        out_valid = (cnt_q >= 4'd3);
        out_data  = out_valid ? {buf_q[2], buf_q[1], buf_q[0]} : '0;
        out_fire  = out_valid && out_ready && !rst;
        if (rst)
            in_ready = 1'b0;
        else if (out_fire)
            in_ready = (n <= 7);
        else
            in_ready = (n <= 4);
        in_fire = in_valid && in_ready && !rst;
    end

    always_comb begin
        // Remove three oldest units on output transfer
        for (int i = 0; i < 8; i++) begin
            if (out_fire) begin
                if (i + 3 < 8)
                    nxt[i] = buf_q[i+3];
                else
                    nxt[i] = '0;
            end else begin
                nxt[i] = buf_q[i];
            end
        end

        m = out_fire ? (n - 3) : n;

        // Append four new units behind remaining units
        if (in_fire) begin
            for (int k = 0; k < 4; k++) begin
                for (int i = 0; i < 8; i++) begin
                    if (i == m + k)
                        nxt[i] = in_data[k*UNIT_W +: UNIT_W];
                end
            end
        end

        cnt_n = 4'(m + (in_fire ? 4 : 0));
    end

    always_ff @(posedge clk) begin
        for (int i = 0; i < 8; i++) begin
            buf_q[i] <= nxt[i];
        end
    end

    always_ff @(posedge clk) begin
        if (rst)
            cnt_q <= '0;
        else
            cnt_q <= cnt_n;
    end

endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);

    localparam integer DEPTH = 8;

    logic [UNIT_W-1:0] mem [0:DEPTH-1];
    logic [3:0]        cnt;

    logic              xfer;
    logic              in_xfer;
    logic [3:0]        cnt_after;
    logic [UNIT_W-1:0] base [0:DEPTH-1];
    logic [UNIT_W-1:0] nxt  [0:DEPTH-1];
    logic [3:0]        cnt_next;

    always_comb begin
        out_valid = (cnt >= 4'd3);
        out_data  = out_valid ? {mem[2], mem[1], mem[0]} : '0;
        xfer      = out_valid && out_ready;

        cnt_after = xfer ? (cnt - 4'd3) : cnt;
        in_ready  = !rst && (cnt_after <= 4'd4);
        in_xfer   = in_valid && in_ready;

        for (int i = 0; i < DEPTH; i++) begin
            if (xfer && (i + 3 < DEPTH))
                base[i] = mem[(i + 3) % DEPTH];
            else
                base[i] = mem[i];
        end

        for (int i = 0; i < DEPTH; i++)
            nxt[i] = base[i];

        if (in_xfer) begin
            for (int k = 0; k < 4; k++)
                nxt[cnt_after + 4'(k)] = in_data[k*UNIT_W +: UNIT_W];
        end

        cnt_next = in_xfer ? (cnt_after + 4'd4) : cnt_after;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            cnt <= '0;
        end else begin
            cnt <= cnt_next;
            for (int i = 0; i < DEPTH; i++)
                mem[i] <= nxt[i];
        end
    end

endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);

    logic [UNIT_W-1:0] mem_q [0:7];
    logic [UNIT_W-1:0] mem_n [0:7];
    logic [3:0]        cnt_q;
    logic [3:0]        cnt_n;
    logic [3:0]        base;
    logic              out_fire;
    logic              in_fire;

    assign out_valid = (cnt_q >= 4'd3);
    assign out_data  = out_valid ? {mem_q[2], mem_q[1], mem_q[0]} : '0;

    assign in_ready = !rst && ((cnt_q <= 4'd4) || ((cnt_q <= 4'd7) && out_ready));

    assign out_fire = !rst && out_valid && out_ready;
    assign in_fire  = !rst && in_valid && in_ready;

    always_comb begin
        base = out_fire ? (cnt_q - 4'd3) : cnt_q;
        for (int i = 0; i < 8; i++) begin
            if (out_fire) begin
                if (i + 3 < 8) mem_n[i] = mem_q[(i + 3) % 8];
                else           mem_n[i] = '0;
            end else begin
                mem_n[i] = mem_q[i];
            end
        end
        if (in_fire) begin
            for (int j = 0; j < 8; j++) begin
                for (int k = 0; k < 4; k++) begin
                    if (base + 4'(k) == 4'(j))
                        mem_n[j] = in_data[k*UNIT_W +: UNIT_W];
                end
            end
            cnt_n = base + 4'd4;
        end else begin
            cnt_n = base;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            cnt_q <= '0;
            for (int i = 0; i < 8; i++) mem_q[i] <= '0;
        end else begin
            cnt_q <= cnt_n;
            for (int i = 0; i < 8; i++) mem_q[i] <= mem_n[i];
        end
    end

endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);

    localparam int AW = $clog2(DEPTH);   // memory address width
    localparam int PW = AW + 1;          // pointer width including wrap bit

    // Storage (not cleared by reset)
    logic [W-1:0] mem [0:DEPTH-1];

    // Write domain state
    logic [PW-1:0] wbin;
    logic [PW-1:0] wgray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] rg1;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] rg2;

    // Read domain state
    logic [PW-1:0] rbin;
    logic [PW-1:0] rgray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] wg1;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] wg2;

    function automatic logic [PW-1:0] bin2gray(input logic [PW-1:0] b);
        bin2gray = b ^ (b >> 1);
    endfunction

    function automatic logic [PW-1:0] gray2bin(input logic [PW-1:0] g);
        logic [PW-1:0] b;
        b[PW-1] = g[PW-1];
        for (int i = PW-2; i >= 0; i--) begin
            b[i] = b[i+1] ^ g[i];
        end
        gray2bin = b;
    endfunction

    // ---------------- Write domain ----------------
    logic             wr_fire;
    logic [PW-1:0]    wbin_nxt;
    logic [PW-1:0]    rbin_sync;
    logic             full_nxt;

    assign wr_fire  = wr_en && !full;
    assign wbin_nxt = wbin + {{(PW-1){1'b0}}, wr_fire};
    assign rbin_sync = gray2bin(rg2);
    // Full when next write pointer is DEPTH ahead of synchronized read pointer
    assign full_nxt = (wbin_nxt == {~rbin_sync[PW-1], rbin_sync[PW-2:0]});

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wbin  <= '0;
            wgray <= '0;
            rg1   <= '0;
            rg2   <= '0;
            full  <= 1'b0;
        end else begin
            rg1   <= rgray;
            rg2   <= rg1;
            wbin  <= wbin_nxt;
            wgray <= bin2gray(wbin_nxt);
            full  <= full_nxt;
        end
    end

    always_ff @(posedge wr_clk) begin
        if (wr_fire) begin
            mem[wbin[AW-1:0]] <= din;
        end
    end

    // ---------------- Read domain ----------------
    logic             rd_fire;
    logic [PW-1:0]    rbin_nxt;
    logic [PW-1:0]    rgray_nxt;
    logic             empty_nxt;

    assign rd_fire   = rd_en && !empty;
    assign rbin_nxt  = rbin + {{(PW-1){1'b0}}, rd_fire};
    assign rgray_nxt = bin2gray(rbin_nxt);
    // Empty when next read pointer equals synchronized write pointer (Gray equality)
    assign empty_nxt = (rgray_nxt == wg2);

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rbin  <= '0;
            rgray <= '0;
            wg1   <= '0;
            wg2   <= '0;
            empty <= 1'b1;
            dout  <= '0;
        end else begin
            wg1   <= wgray;
            wg2   <= wg1;
            rbin  <= rbin_nxt;
            rgray <= rgray_nxt;
            empty <= empty_nxt;
            if (rd_fire) begin
                dout <= mem[rbin[AW-1:0]];
            end
        end
    end

endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);

    localparam int AW = $clog2(DEPTH);   // memory address width
    localparam int PW = AW + 1;          // pointer width incl. wrap bit

    // Gray-to-binary conversion (combinational)
    function automatic logic [PW-1:0] g2b(input logic [PW-1:0] g);
        logic [PW-1:0] b;
        int i;
        begin
            b[PW-1] = g[PW-1];
            for (i = PW - 2; i >= 0; i--) begin
                b[i] = b[i+1] ^ g[i];
            end
            g2b = b;
        end
    endfunction

    logic [W-1:0] mem [DEPTH];

    // Write domain state
    logic [PW-1:0] wbin;
    logic [PW-1:0] wgray;
    logic [PW-1:0] wbin_nx;
    logic          wr_acc;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] rq1_gray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] rq2_gray;
    logic [PW-1:0] rq2_bin;

    // Read domain state
    logic [PW-1:0] rbin;
    logic [PW-1:0] rgray;
    logic [PW-1:0] rbin_nx;
    logic          rd_acc;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] wq1_gray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] wq2_gray;
    logic [PW-1:0] wq2_bin;

    assign rq2_bin = g2b(rq2_gray);
    assign wq2_bin = g2b(wq2_gray);

    // ---------------- Write domain ----------------
    assign wr_acc  = wr_en && !full;
    assign wbin_nx = wr_acc ? (wbin + PW'(1)) : wbin;

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wbin     <= '0;
            wgray    <= '0;
            rq1_gray <= '0;
            rq2_gray <= '0;
            full     <= 1'b0;
        end else begin
            wbin     <= wbin_nx;
            wgray    <= wbin_nx ^ (wbin_nx >> 1);
            rq1_gray <= rgray;
            rq2_gray <= rq1_gray;
            full     <= (wbin_nx == {~rq2_bin[PW-1], rq2_bin[PW-2:0]});
            if (wr_acc) begin
                mem[wbin[AW-1:0]] <= din;
            end
        end
    end

    // ---------------- Read domain ----------------
    assign rd_acc  = rd_en && !empty;
    assign rbin_nx = rd_acc ? (rbin + PW'(1)) : rbin;

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rbin     <= '0;
            rgray    <= '0;
            wq1_gray <= '0;
            wq2_gray <= '0;
            empty    <= 1'b1;
            dout     <= '0;
        end else begin
            rbin     <= rbin_nx;
            rgray    <= rbin_nx ^ (rbin_nx >> 1);
            wq1_gray <= wgray;
            wq2_gray <= wq1_gray;
            empty    <= (rbin_nx == wq2_bin);
            if (rd_acc) begin
                dout <= mem[rbin[AW-1:0]];
            end
        end
    end

endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);

    localparam int AW = $clog2(DEPTH);   // memory address width
    localparam int P  = AW + 1;          // pointer width including wrap bit

    // Gray-code mask that inverts the two MSBs (used for the full comparison)
    localparam logic [P-1:0] FULL_MASK = {2'b11, {(P-2){1'b0}}};

    logic [W-1:0] mem [DEPTH];

    // ---------------- Write domain ----------------
    logic [P-1:0] wptr;
    logic [P-1:0] wgray;
    (* ASYNC_REG = "TRUE" *) logic [P-1:0] rsync1;
    (* ASYNC_REG = "TRUE" *) logic [P-1:0] rsync2;

    logic         wr_fire;
    logic [P-1:0] wptr_n;
    logic [P-1:0] wgray_n;
    logic         full_n;

    assign wr_fire = wr_en & ~full;
    assign wptr_n  = wr_fire ? (wptr + 1'b1) : wptr;
    assign wgray_n = wptr_n ^ (wptr_n >> 1);
    // Full: next write pointer is DEPTH ahead of synchronized read pointer
    assign full_n  = (wgray_n == (rsync2 ^ FULL_MASK));

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wptr   <= '0;
            wgray  <= '0;
            rsync1 <= '0;
            rsync2 <= '0;
            full   <= 1'b0;
        end else begin
            if (wr_fire) mem[wptr[AW-1:0]] <= din;
            wptr   <= wptr_n;
            wgray  <= wgray_n;
            rsync1 <= rgray_q;
            rsync2 <= rsync1;
            full   <= full_n;
        end
    end

    // ---------------- Read domain ----------------
    logic [P-1:0] rptr;
    logic [P-1:0] rgray_q;
    (* ASYNC_REG = "TRUE" *) logic [P-1:0] wsync1;
    (* ASYNC_REG = "TRUE" *) logic [P-1:0] wsync2;

    logic         rd_fire;
    logic [P-1:0] rptr_n;
    logic [P-1:0] rgray_n;
    logic         empty_n;

    assign rd_fire  = rd_en & ~empty;
    assign rptr_n   = rd_fire ? (rptr + 1'b1) : rptr;
    assign rgray_n  = rptr_n ^ (rptr_n >> 1);
    assign empty_n  = (rgray_n == wsync2);

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rptr    <= '0;
            rgray_q <= '0;
            wsync1  <= '0;
            wsync2  <= '0;
            empty   <= 1'b1;
            dout    <= '0;
        end else begin
            if (rd_fire) dout <= mem[rptr[AW-1:0]];
            rptr    <= rptr_n;
            rgray_q <= rgray_n;
            wsync1  <= wgray;
            wsync2  <= wsync1;
            empty   <= empty_n;
        end
    end

endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
