    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);

    localparam int MEM_BYTES = 1 << ADDR_W;

    logic [7:0] mem [0:MEM_BYTES-1];

    // Write state
    logic              wcap;
    logic [ADDR_W-1:0] waddr;
    logic [LEN_W-1:0]  wrem;
    logic [ID_W-1:0]   wid_q;
    logic              wlegal;
    logic              wmis;

    // Read state
    logic [ADDR_W-1:0] raddr;
    logic [ID_W-1:0]   rid_q;
    logic [LEN_W-1:0]  rrem;
    logic              rlegal;

    // Handshake / helper signals
    logic aw_hs, w_hs, b_hs, ar_hs, r_hs;
    logic w_final, w_mis_now;
    logic [ADDR_W-1:0] raddr_nxt;

    function automatic logic legal_desc(
        input logic [2:0]        sz,
        input logic [1:0]        bst,
        input logic              lk,
        input logic [ADDR_W-1:0] a,
        input logic [LEN_W-1:0]  l
    );
        logic [15:0] fin;
        logic [15:0] lim;
        fin = 16'(a) + (16'(l) << 2);
        lim = 16'(MEM_BYTES);
        legal_desc = (sz == 3'd2) && (bst == 2'b01) && (!lk) &&
                     (a[1:0] == 2'b00) && (fin < lim);
    endfunction

    function automatic logic [31:0] word_at(input logic [ADDR_W-1:0] a);
        logic [ADDR_W-1:0] b;
        b = {a[ADDR_W-1:2], 2'b00};
        word_at = {mem[{b[ADDR_W-1:2], 2'd3}],
                   mem[{b[ADDR_W-1:2], 2'd2}],
                   mem[{b[ADDR_W-1:2], 2'd1}],
                   mem[{b[ADDR_W-1:2], 2'd0}]};
    endfunction

    assign s_axi_awready = !rst && !wcap && !s_axi_bvalid;
    assign s_axi_wready  = !rst && wcap;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    assign aw_hs = s_axi_awvalid && s_axi_awready;
    assign w_hs  = s_axi_wvalid  && s_axi_wready;
    assign b_hs  = s_axi_bvalid  && s_axi_bready;
    assign ar_hs = s_axi_arvalid && s_axi_arready;
    assign r_hs  = s_axi_rvalid  && s_axi_rready;

    assign w_final   = (wrem == '0);
    assign w_mis_now = (s_axi_wlast != w_final);
    assign raddr_nxt = raddr + ADDR_W'(4);

    assign s_axi_bid   = s_axi_bid_q;
    assign s_axi_rid   = rid_out;

    logic [ID_W-1:0] s_axi_bid_q;
    logic [ID_W-1:0] rid_out;

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int k = 0; k < MEM_BYTES; k++) begin
                mem[k] <= 8'd0;
            end
            wcap           <= 1'b0;
            waddr          <= '0;
            wrem           <= '0;
            wid_q          <= '0;
            wlegal         <= 1'b0;
            wmis           <= 1'b0;
            s_axi_bid_q    <= '0;
            s_axi_bresp    <= 2'b00;
            s_axi_bvalid   <= 1'b0;
            raddr          <= '0;
            rid_q          <= '0;
            rrem           <= '0;
            rlegal         <= 1'b0;
            rid_out        <= '0;
            s_axi_rdata    <= 32'd0;
            s_axi_rresp    <= 2'b00;
            s_axi_rlast    <= 1'b0;
            s_axi_rvalid   <= 1'b0;
        end else begin
            // ---------------- Write path ----------------
            if (aw_hs) begin
                wcap   <= 1'b1;
                waddr  <= s_axi_awaddr;
                wrem   <= s_axi_awlen;
                wid_q  <= s_axi_awid;
                wlegal <= legal_desc(s_axi_awsize, s_axi_awburst, s_axi_awlock,
                                     s_axi_awaddr, s_axi_awlen);
                wmis   <= 1'b0;
            end

            if (b_hs) begin
                s_axi_bvalid <= 1'b0;
            end

            if (w_hs) begin
                if (wlegal) begin
                    for (int i = 0; i < 4; i++) begin
                        if (s_axi_wstrb[i]) begin
                            mem[{waddr[ADDR_W-1:2], 2'(i)}] <= s_axi_wdata[8*i +: 8];
                        end
                    end
                end
                wrem  <= wrem - LEN_W'(1);
                waddr <= waddr + ADDR_W'(4);
                if (w_final) begin
                    wcap         <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid_q  <= wid_q;
                    s_axi_bresp  <= (wlegal && !wmis && !w_mis_now) ? 2'b00 : 2'b10;
                end else begin
                    wmis <= wmis | w_mis_now;
                end
            end

            // ---------------- Read path ----------------
            if (ar_hs) begin
                raddr        <= s_axi_araddr;
                rid_q        <= s_axi_arid;
                rid_out      <= s_axi_arid;
                rrem         <= s_axi_arlen;
                rlegal       <= legal_desc(s_axi_arsize, s_axi_arburst, s_axi_arlock,
                                           s_axi_araddr, s_axi_arlen);
                s_axi_rvalid <= 1'b1;
                s_axi_rlast  <= (s_axi_arlen == '0);
                s_axi_rresp  <= legal_desc(s_axi_arsize, s_axi_arburst, s_axi_arlock,
                                           s_axi_araddr, s_axi_arlen) ? 2'b00 : 2'b10;
                s_axi_rdata  <= legal_desc(s_axi_arsize, s_axi_arburst, s_axi_arlock,
                                           s_axi_araddr, s_axi_arlen) ?
                                word_at(s_axi_araddr) : 32'd0;
            end else if (r_hs) begin
                if (s_axi_rlast) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    raddr       <= raddr_nxt;
                    rrem        <= rrem - LEN_W'(1);
                    s_axi_rlast <= (rrem == LEN_W'(1));
                    s_axi_rdata <= rlegal ? word_at(raddr_nxt) : 32'd0;
                end
            end
        end
    end

    assign s_axi_bid = s_axi_bid_q;
    assign s_axi_rid = rid_out;

endmodule

