module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);

    localparam int MEM_N = 1 << ADDR_W;

    logic [7:0] mem [0:MEM_N-1];

    // ------------------------------------------------------------------
    // Legality check
    // ------------------------------------------------------------------
    function automatic logic is_legal(input logic [ADDR_W-1:0] a,
                                      input logic [LEN_W-1:0]  l,
                                      input logic [2:0]        sz,
                                      input logic [1:0]        bu,
                                      input logic              lk);
        logic [12:0] end_a;
        begin
            end_a = 13'(a) + (13'(l) << 2);
            is_legal = (sz == 3'd2) && (bu == 2'b01) && !lk &&
                       (a[1:0] == 2'b00) && (end_a < (13'd1 << ADDR_W));
        end
    endfunction

    // Aligned word read helper
    function automatic logic [31:0] rd_word(input logic [ADDR_W-1:0] a);
        begin
            rd_word = {mem[{a[ADDR_W-1:2], 2'd3}],
                       mem[{a[ADDR_W-1:2], 2'd2}],
                       mem[{a[ADDR_W-1:2], 2'd1}],
                       mem[{a[ADDR_W-1:2], 2'd0}]};
        end
    endfunction

    // ------------------------------------------------------------------
    // Write channel state
    // ------------------------------------------------------------------
    logic              wr_busy;
    logic [ID_W-1:0]   wr_id;
    logic [ADDR_W-1:0] wr_addr;
    logic [LEN_W-1:0]  wr_len;
    logic [LEN_W-1:0]  wr_cnt;
    logic              wr_legal;
    logic              wr_err;

