    logic aw_legal_in;

    assign aw_legal_in = is_legal(s_axi_awaddr, s_axi_awlen, s_axi_awsize,
                                  s_axi_awburst, s_axi_awlock);

    assign s_axi_awready = !rst && !wr_busy && !s_axi_bvalid;
    assign s_axi_wready  = !rst && wr_busy;

    assign aw_hs = s_axi_awvalid && s_axi_awready;
    assign w_hs  = s_axi_wvalid && s_axi_wready;

    logic wr_is_last;
    logic wr_mismatch;
    assign wr_is_last  = (wr_cnt == wr_len);
    assign wr_mismatch = (s_axi_wlast != wr_is_last);

    always_ff @(posedge clk) begin
        if (rst) begin
            wr_busy        <= 1'b0;
            wr_id          <= '0;
            wr_addr        <= '0;
            wr_len         <= '0;
            wr_cnt         <= '0;
            wr_legal       <= 1'b0;
            wr_err         <= 1'b0;
            s_axi_bvalid   <= 1'b0;
            s_axi_bid      <= '0;
            s_axi_bresp    <= 2'b00;
        end else begin
            if (aw_hs) begin
                wr_busy  <= 1'b1;
                wr_id    <= s_axi_awid;
                wr_addr  <= s_axi_awaddr;
                wr_len   <= s_axi_awlen;
                wr_cnt   <= '0;
                wr_legal <= aw_legal_in;
                wr_err   <= 1'b0;
            end

            if (w_hs) begin
                wr_addr <= wr_addr + ADDR_W'(4);
                wr_cnt  <= wr_cnt + LEN_W'(1);
                if (wr_is_last) begin
                    wr_busy      <= 1'b0;
                    wr_err       <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid    <= wr_id;
                    s_axi_bresp  <= (wr_legal && !wr_err && !wr_mismatch) ? 2'b00 : 2'b10;
                end else begin
                    wr_err <= wr_err | wr_mismatch;
                end
            end

            if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Memory write (byte-lane enables)
    // ------------------------------------------------------------------
    logic [ADDR_W-1:0] wbase;
    assign wbase = {wr_addr[ADDR_W-1:2], 2'b00};

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int i = 0; i < MEM_N; i++) begin
                mem[i] <= 8'h00;
            end
        end else if (w_hs && wr_legal) begin
            for (int i = 0; i < 4; i++) begin
                if (s_axi_wstrb[i]) begin
                    mem[wbase + ADDR_W'(i)] <= s_axi_wdata[8*i +: 8];
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel state
    // ------------------------------------------------------------------
    logic              rd_legal;
    logic [ADDR_W-1:0] rd_addr;
    logic [LEN_W-1:0]  rd_len;
    logic [LEN_W-1:0]  rd_cnt;
    logic              ar_hs;
    logic              ar_legal_in;

    assign ar_legal_in = is_legal(s_axi_araddr, s_axi_arlen, s_axi_arsize,
                                  s_axi_arburst, s_axi_arlock);

    assign s_axi_arready = !rst && !s_axi_rvalid;
    assign ar_hs = s_axi_arvalid && s_axi_arready;

    always_ff @(posedge clk) begin
        if (rst) begin
            rd_legal      <= 1'b0;
            rd_addr       <= '0;
            rd_len        <= '0;
            rd_cnt        <= '0;
            s_axi_rvalid  <= 1'b0;
            s_axi_rid     <= '0;
            s_axi_rresp   <= 2'b00;
            s_axi_rlast   <= 1'b0;
            s_axi_rdata   <= '0;
        end else begin
            if (ar_hs) begin
                rd_legal     <= ar_legal_in;
                rd_addr      <= s_axi_araddr;
                rd_len       <= s_axi_arlen;
                rd_cnt       <= '0;
                s_axi_rvalid <= 1'b1;
                s_axi_rid    <= s_axi_arid;
                s_axi_rresp  <= ar_legal_in ? 2'b00 : 2'b10;
                s_axi_rlast  <= (s_axi_arlen == '0);
                s_axi_rdata  <= ar_legal_in ? rd_word(s_axi_araddr) : 32'd0;
            end else if (s_axi_rvalid && s_axi_rready) begin
                if (s_axi_rlast) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    rd_cnt      <= rd_cnt + LEN_W'(1);
                    rd_addr     <= rd_addr + ADDR_W'(4);
                    s_axi_rdata <= rd_legal ? rd_word(rd_addr + ADDR_W'(4)) : 32'd0;
                    s_axi_rlast <= ((rd_cnt + LEN_W'(1)) == rd_len);
                end
            end
        end
    end

endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);

    localparam int NW = 1 << (ADDR_W - 2);

    logic [31:0] mem [0:NW-1];

    // write state
    logic                 wbusy;
    logic                 wlegal;
    logic                 werr;
    logic [LEN_W-1:0]     wcnt;
    logic [LEN_W-1:0]     wlen_q;
    logic [ID_W-1:0]      wid_q;
    logic [ADDR_W-3:0]    widx;

    // read state
    logic                 rlegal;
    logic [LEN_W-1:0]     rcnt;
    logic [LEN_W-1:0]     rlen_q;
    logic [ADDR_W-3:0]    ridx;

    // legality check
    function automatic logic burst_ok(
        input logic [ADDR_W-1:0] a,
        input logic [LEN_W-1:0]  l,
        input logic [2:0]        sz,
        input logic [1:0]        bt,
        input logic              lk
    );
        logic [15:0] last;
        logic [15:0] aw16;
        logic [15:0] lw16;
        begin
            aw16 = {{(16-ADDR_W){1'b0}}, a};
            lw16 = {{(16-LEN_W){1'b0}}, l};
            last = aw16 + (lw16 << 2);
            burst_ok = (sz == 3'd2) && (bt == 2'b01) && (!lk) &&
                       (a[1:0] == 2'b00) && (last < (16'd1 << ADDR_W));
        end
    endfunction

    logic aw_legal, ar_legal;
    assign aw_legal = burst_ok(s_axi_awaddr, s_axi_awlen, s_axi_awsize,
                               s_axi_awburst, s_axi_awlock);
    assign ar_legal = burst_ok(s_axi_araddr, s_axi_arlen, s_axi_arsize,
                               s_axi_arburst, s_axi_arlock);

    // handshakes / ready
    logic aw_hs, w_hs, b_hs, ar_hs, r_hs;
    logic is_last_w, wrong;

    assign s_axi_awready = !rst && !wbusy && !s_axi_bvalid;
    assign s_axi_wready  = !rst && wbusy;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    assign aw_hs = s_axi_awvalid && s_axi_awready;
    assign w_hs  = s_axi_wvalid  && s_axi_wready;
    assign b_hs  = s_axi_bvalid  && s_axi_bready;
    assign ar_hs = s_axi_arvalid && s_axi_arready;
    assign r_hs  = s_axi_rvalid  && s_axi_rready;

    assign is_last_w = (wcnt == wlen_q);
    assign wrong     = (s_axi_wlast != is_last_w);

    integer i;

    always_ff @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < NW; i = i + 1) begin
                mem[i] <= 32'd0;
            end
            wbusy        <= 1'b0;
            wlegal       <= 1'b0;
            werr         <= 1'b0;
            wcnt         <= '0;
            wlen_q       <= '0;
            wid_q        <= '0;
            widx         <= '0;
            s_axi_bvalid <= 1'b0;
            s_axi_bid    <= '0;
            s_axi_bresp  <= 2'b00;

            rlegal       <= 1'b0;
            rcnt         <= '0;
            rlen_q       <= '0;
            ridx         <= '0;
            s_axi_rvalid <= 1'b0;
            s_axi_rid    <= '0;
            s_axi_rresp  <= 2'b00;
            s_axi_rlast  <= 1'b0;
            s_axi_rdata  <= 32'd0;
        end else begin
            // ---------------- write path ----------------
            if (aw_hs) begin
                wbusy  <= 1'b1;
                wcnt   <= '0;
                wlen_q <= s_axi_awlen;
                wid_q  <= s_axi_awid;
                wlegal <= aw_legal;
                werr   <= 1'b0;
                widx   <= s_axi_awaddr[ADDR_W-1:2];
            end else if (w_hs) begin
                widx <= widx + 1'b1;
                wcnt <= wcnt + 1'b1;
                if (wrong) werr <= 1'b1;
                if (is_last_w) begin
                    wbusy        <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid    <= wid_q;
                    s_axi_bresp  <= (wlegal && !werr && !wrong) ? 2'b00 : 2'b10;
                end
            end

            if (b_hs) s_axi_bvalid <= 1'b0;

            if (w_hs && wlegal) begin
                for (i = 0; i < 4; i = i + 1) begin
                    if (s_axi_wstrb[i]) begin
                        mem[widx][8*i +: 8] <= s_axi_wdata[8*i +: 8];
                    end
                end
            end

            // ---------------- read path ----------------
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rid    <= s_axi_arid;
                rlegal       <= ar_legal;
                rlen_q       <= s_axi_arlen;
                rcnt         <= '0;
                ridx         <= s_axi_araddr[ADDR_W-1:2];
                s_axi_rlast  <= (s_axi_arlen == '0);
                s_axi_rresp  <= ar_legal ? 2'b00 : 2'b10;
                if (ar_legal) s_axi_rdata <= mem[s_axi_araddr[ADDR_W-1:2]];
                else          s_axi_rdata <= 32'd0;
            end else if (r_hs) begin
                if (rcnt == rlen_q) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    rcnt        <= rcnt + 1'b1;
                    ridx        <= ridx + 1'b1;
                    s_axi_rlast <= ((rcnt + 1'b1) == rlen_q);
                    if (rlegal) s_axi_rdata <= mem[ridx + 1'b1];
                    else        s_axi_rdata <= 32'd0;
                end
            end
        end
    end

endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);

    typedef enum logic [1:0] {
        S_IDLE    = 2'd0,
        S_MEM_REQ = 2'd1,
        S_REFILL  = 2'd2,
        S_RSP     = 2'd3
    } state_t;

    state_t                      state;
    logic [TAG_W+INDEX_W:0]      req_addr_q;
    logic [DATA_W-1:0]           rsp_data_q;
    logic [2**INDEX_W-1:0]       valid_q;
    logic [TAG_W-1:0]            tag_mem  [2**INDEX_W];
    logic [2*DATA_W-1:0]         data_mem [2**INDEX_W];

    // Current CPU request fields
    logic [INDEX_W-1:0]          cur_idx;
    logic [TAG_W-1:0]            cur_tag;
    logic                        cur_off;
    assign cur_idx = cpu_req_addr[INDEX_W:1];
    assign cur_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    assign cur_off = cpu_req_addr[0];

    // Saved miss request fields
    logic [INDEX_W-1:0]          req_idx;
    logic [TAG_W-1:0]            req_tag;
    logic                        req_off;
    assign req_idx = req_addr_q[INDEX_W:1];
    assign req_tag = req_addr_q[TAG_W+INDEX_W:INDEX_W+1];
    assign req_off = req_addr_q[0];

    logic                        cur_hit;
    logic [DATA_W-1:0]           cur_word;
    assign cur_hit  = valid_q[cur_idx] && (tag_mem[cur_idx] == cur_tag);
    assign cur_word = cur_off ? data_mem[cur_idx][DATA_W +: DATA_W]
                              : data_mem[cur_idx][DATA_W-1:0];

    // Handshake outputs
    assign inv_ready      = !rst && (state == S_IDLE);
    assign cpu_req_ready  = !rst && (state == S_IDLE) && !inv_valid;
    assign cpu_rsp_valid  = !rst && (state == S_RSP);
    assign cpu_rsp_data   = cpu_rsp_valid ? rsp_data_q : '0;
    assign mem_req_valid  = !rst && (state == S_MEM_REQ);
    assign mem_req_addr   = mem_req_valid ? req_addr_q[TAG_W+INDEX_W:1] : '0;
    assign mem_rsp_ready  = !rst && (state == S_REFILL);

    logic cpu_accept;
    assign cpu_accept = cpu_req_valid && cpu_req_ready;

    // Control state, valid bits, saved request
    always_ff @(posedge clk) begin
        if (rst) begin
            state      <= S_IDLE;
            valid_q    <= '0;
            req_addr_q <= '0;
            rsp_data_q <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        valid_q <= '0;
                    end else if (cpu_accept) begin
                        if (cur_hit) begin
                            rsp_data_q <= cur_word;
                            state      <= S_RSP;
                        end else begin
                            req_addr_q <= cpu_req_addr;
                            state      <= S_MEM_REQ;
                        end
                    end
                end

                S_MEM_REQ: begin
                    if (mem_req_ready) begin
                        state <= S_REFILL;
                    end
                end

                S_REFILL: begin
                    if (mem_rsp_valid) begin
                        rsp_data_q <= req_off ? mem_rsp_data[DATA_W +: DATA_W]
                                              : mem_rsp_data[DATA_W-1:0];
                        valid_q[req_idx] <= 1'b1;
                        state            <= S_RSP;
                    end
                end

                S_RSP: begin
                    if (cpu_rsp_ready) begin
                        state <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

    // Data and tag arrays (no reset needed; invalid entries are don't-care)
    always_ff @(posedge clk) begin
        if (!rst && (state == S_REFILL) && mem_rsp_valid) begin
            data_mem[req_idx] <= mem_rsp_data;
            tag_mem[req_idx]  <= req_tag;
        end
    end

endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);

    localparam int LINES  = 1 << INDEX_W;
    localparam int ADDR_W = TAG_W + INDEX_W + 1;

    typedef enum logic [1:0] {
        S_IDLE = 2'd0,
        S_MREQ = 2'd1,
        S_MRSP = 2'd2,
        S_RSP  = 2'd3
    } state_t;

    state_t                    state;
    logic [ADDR_W-1:0]         req_addr;
    logic [DATA_W-1:0]         rsp_reg;
    logic [LINES-1:0]          valid;
    logic [TAG_W-1:0]          tags  [LINES];
    logic [2*DATA_W-1:0]       lines [LINES];

    // CPU lookup fields
    logic [INDEX_W-1:0]        c_idx;
    logic [TAG_W-1:0]          c_tag;
    logic                      c_hit;
    logic [DATA_W-1:0]         c_word;

    assign c_idx = cpu_req_addr[INDEX_W:1];
    assign c_tag = cpu_req_addr[ADDR_W-1:INDEX_W+1];
    assign c_hit = valid[c_idx] && (tags[c_idx] == c_tag);
    assign c_word = cpu_req_addr[0] ? lines[c_idx][2*DATA_W-1:DATA_W]
                                    : lines[c_idx][DATA_W-1:0];

    // Refill fields
    logic [INDEX_W-1:0]        r_idx;
    logic [TAG_W-1:0]          r_tag;
    logic [DATA_W-1:0]         r_word;

    assign r_idx  = req_addr[INDEX_W:1];
    assign r_tag  = req_addr[ADDR_W-1:INDEX_W+1];
    assign r_word = req_addr[0] ? mem_rsp_data[2*DATA_W-1:DATA_W]
                                : mem_rsp_data[DATA_W-1:0];

    // Output logic
    assign inv_ready     = !rst && (state == S_IDLE);
    assign cpu_req_ready = !rst && (state == S_IDLE) && !inv_valid;
    assign cpu_rsp_valid = !rst && (state == S_RSP);
    assign cpu_rsp_data  = cpu_rsp_valid ? rsp_reg : '0;
    assign mem_req_valid = !rst && (state == S_MREQ);
    assign mem_req_addr  = mem_req_valid ? req_addr[ADDR_W-1:1] : '0;
    assign mem_rsp_ready = !rst && (state == S_MRSP);

    always_ff @(posedge clk) begin
        if (rst) begin
            state   <= S_IDLE;
            valid   <= '0;
            req_addr <= '0;
            rsp_reg <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        valid <= '0;
                    end else if (cpu_req_valid) begin
                        if (c_hit) begin
                            rsp_reg <= c_word;
                            state   <= S_RSP;
                        end else begin
                            req_addr <= cpu_req_addr;
                            state    <= S_MREQ;
                        end
                    end
                end

                S_MREQ: begin
                    if (mem_req_ready) begin
                        state <= S_MRSP;
                    end
                end

                S_MRSP: begin
                    if (mem_rsp_valid) begin
                        lines[r_idx] <= mem_rsp_data;
                        tags[r_idx]  <= r_tag;
                        valid[r_idx] <= 1'b1;
                        rsp_reg      <= r_word;
                        state        <= S_RSP;
                    end
                end

                S_RSP: begin
                    if (cpu_rsp_ready) begin
                        state <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);

    typedef enum logic [1:0] {
        S_IDLE    = 2'd0,
        S_MEM_REQ = 2'd1,
        S_MEM_RSP = 2'd2,
        S_RSP     = 2'd3
    } state_t;

    state_t state;

    logic [TAG_W+INDEX_W:0]  req_addr;   // saved full CPU word address
    logic [DATA_W-1:0]       rsp_data;   // registered CPU response word

    logic [2*DATA_W-1:0]     line_data  [2**INDEX_W];
    logic [TAG_W-1:0]        line_tag   [2**INDEX_W];
    logic [2**INDEX_W-1:0]   line_valid;

    // Pre-edge lookup of the incoming CPU request
    logic [INDEX_W-1:0] cur_idx;
    logic [TAG_W-1:0]   cur_tag;
    logic               cur_off;
    logic               hit;
    logic [DATA_W-1:0]  cur_word;

    assign cur_idx = cpu_req_addr[INDEX_W:1];
    assign cur_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    assign cur_off = cpu_req_addr[0];

    always_comb begin
        hit = line_valid[cur_idx] && (line_tag[cur_idx] == cur_tag);
        if (cur_off)
            cur_word = line_data[cur_idx][2*DATA_W-1:DATA_W];
        else
            cur_word = line_data[cur_idx][DATA_W-1:0];
    end

    // Refill-side fields from saved request
    logic [INDEX_W-1:0] req_idx;
    logic [TAG_W-1:0]   req_tag;
    logic               req_off;
    assign req_idx = req_addr[INDEX_W:1];
    assign req_tag = req_addr[TAG_W+INDEX_W:INDEX_W+1];
    assign req_off = req_addr[0];

    logic [DATA_W-1:0] refill_word;
    assign refill_word = req_off ? mem_rsp_data[2*DATA_W-1:DATA_W]
                                 : mem_rsp_data[DATA_W-1:0];

    // Handshake outputs (all gated by reset)
    assign inv_ready     = !rst && (state == S_IDLE);
    assign cpu_req_ready = !rst && (state == S_IDLE) && !inv_valid;
    assign cpu_rsp_valid = !rst && (state == S_RSP);
    assign mem_req_valid = !rst && (state == S_MEM_REQ);
    assign mem_rsp_ready = !rst && (state == S_MEM_RSP);

    assign mem_req_addr  = mem_req_valid ? req_addr[TAG_W+INDEX_W:1] : '0;
    assign cpu_rsp_data  = cpu_rsp_valid ? rsp_data : '0;

    always_ff @(posedge clk) begin
        if (rst) begin
            state      <= S_IDLE;
            line_valid <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        line_valid <= '0;
                    end else if (cpu_req_valid) begin
                        req_addr <= cpu_req_addr;
                        if (hit) begin
                            rsp_data <= cur_word;
                            state    <= S_RSP;
                        end else begin
                            state    <= S_MEM_REQ;
                        end
                    end
                end

                S_MEM_REQ: begin
                    if (mem_req_ready)
                        state <= S_MEM_RSP;
                end

                S_MEM_RSP: begin
                    if (mem_rsp_valid) begin
                        line_data[req_idx]  <= mem_rsp_data;
                        line_tag[req_idx]   <= req_tag;
                        line_valid[req_idx] <= 1'b1;
                        rsp_data            <= refill_word;
                        state               <= S_RSP;
                    end
                end

                S_RSP: begin
                    if (cpu_rsp_ready)
                        state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
    input  logic [BYTE_W-1:0]     in_data,
    input  logic                  in_last,
    output logic                  out_valid,
    input  logic                  out_ready,
    output logic [2*BYTE_W-1:0]   out_checksum
);

    localparam integer W = 2*BYTE_W;

    logic [W-1:0]      acc;       // folded running sum of current packet
    logic [BYTE_W-1:0] hold;      // pending upper byte
    logic              have_hi;   // upper byte of a word is held

    logic [W-1:0]   word;
    logic [W:0]     s_full;
    logic [W-1:0]   s_fold;
    logic [W-1:0]   final_sum;
    logic           out_free;
    logic           in_fire;
    logic           out_xfer;

    // Word formed by the current byte
    always_comb begin
        if (have_hi)
            word = {hold, in_data};
        else
            word = {in_data, {BYTE_W{1'b0}}};
    end

    // One's-complement add with end-around carry (single fold suffices)
    always_comb begin
        s_full = {1'b0, acc} + {1'b0, word};
        s_fold = s_full[W-1:0] + {{(W-1){1'b0}}, s_full[W]};
    end

    assign final_sum = s_fold;

    // Output slot can accept a new checksum this cycle
    assign out_free = !out_valid || out_ready;

    always_comb begin
        if (rst)
            in_ready = 1'b0;
        else if (!in_last)
            in_ready = 1'b1;
        else
            in_ready = out_free;
    end

    assign in_fire  = in_valid && in_ready;
    assign out_xfer = out_valid && out_ready;

    always_ff @(posedge clk) begin
        if (rst) begin
            acc       <= '0;
            hold      <= '0;
            have_hi   <= 1'b0;
            out_valid <= 1'b0;
            out_checksum <= '0;
        end else begin
            if (in_fire) begin
                if (in_last) begin
                    acc       <= '0;
                    have_hi   <= 1'b0;
                    out_valid <= 1'b1;
                    out_checksum <= ~final_sum;
                end else if (have_hi) begin
                    acc     <= s_fold;
                    have_hi <= 1'b0;
                end else begin
                    hold    <= in_data;
                    have_hi <= 1'b1;
                end
            end

            if (in_fire && in_last) begin
                // new checksum takes the slot (any old one transferred)
            end else if (out_xfer) begin
                out_valid    <= 1'b0;
                out_checksum <= '0;
            end
        end
    end

endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
    input  logic [BYTE_W-1:0]     in_data,
    input  logic                  in_last,
    output logic                  out_valid,
    input  logic                  out_ready,
    output logic [2*BYTE_W-1:0]  out_checksum
);

    localparam int W = 2*BYTE_W;

    logic              phase;     // 0: next byte is upper half of a word, 1: lower half
    logic [BYTE_W-1:0] hi;        // held upper byte when phase == 1
    logic [W-1:0]      acc;       // folded running sum of the current packet
    logic              ov;        // output slot occupied
    logic [W-1:0]      oc;        // buffered checksum

    assign in_ready     = !rst && (!in_last || !ov || out_ready);
    assign out_valid    = ov;
    assign out_checksum = oc;

    wire accept = in_valid && in_ready;

    // Word formed when completing a pair or when a final byte closes a packet
    wire [W-1:0] word = phase ? {hi, in_data} : {in_data, {BYTE_W{1'b0}}};

    wire [W:0]   s      = {1'b0, acc} + {1'b0, word};
    wire [W-1:0] folded = s[W-1:0] + {{(W-1){1'b0}}, s[W]};

    always_ff @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            hi    <= '0;
            acc   <= '0;
            ov    <= 1'b0;
            oc    <= '0;
        end else begin
            if (accept) begin
                if (in_last) begin
                    acc   <= '0;
                    phase <= 1'b0;
                end else if (phase) begin
                    acc   <= folded;
                    phase <= 1'b0;
                end else begin
                    hi    <= in_data;
                    phase <= 1'b1;
                end
            end

            if (accept && in_last) begin
                ov <= 1'b1;
                oc <= ~folded;
            end else if (ov && out_ready) begin
                ov <= 1'b0;
                oc <= '0;
            end
        end
    end

endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
    input  logic [BYTE_W-1:0]     in_data,
    input  logic                  in_last,
    output logic                  out_valid,
    input  logic                  out_ready,
    output logic [2*BYTE_W-1:0]  out_checksum
);
    localparam int W = 2 * BYTE_W;

    logic              have_hi;
    logic [BYTE_W-1:0] hi_q;
    logic [W-1:0]      sum_q;
    logic              out_v;
    logic [W-1:0]      out_q;

    // One's-complement add of two W-bit words with end-around carry.
    function automatic logic [W-1:0] ones_add(input logic [W-1:0] a,
                                              input logic [W-1:0] b);
        logic [W:0]   t;
        logic [W-1:0] r;
        begin
            t = {1'b0, a} + {1'b0, b};
            r = t[W-1:0] + {{(W-1){1'b0}}, t[W]};
            ones_add = r;
        end
    endfunction

    logic              acc;
    logic [W-1:0]      word;
    logic [W-1:0]      total;
    logic              out_take;

    assign in_ready  = !rst && (!in_last || !out_valid || out_ready);
    assign acc       = in_valid && in_ready;
    assign out_take  = out_v && out_ready;

    // Word formed from the current byte (and held upper byte if present).
    assign word  = have_hi ? {hi_q, in_data} : {in_data, {BYTE_W{1'b0}}};
    assign total = ones_add(sum_q, word);

    assign out_valid    = out_v;
    assign out_checksum = out_v ? out_q : '0;

    always_ff @(posedge clk) begin
        if (rst) begin
            have_hi <= 1'b0;
            hi_q    <= '0;
            sum_q   <= '0;
            out_v   <= 1'b0;
            out_q   <= '0;
        end else begin
            if (acc) begin
                if (in_last) begin
                    sum_q   <= '0;
                    have_hi <= 1'b0;
                    out_v   <= 1'b1;
                    out_q   <= ~total;
                end else if (have_hi) begin
                    sum_q   <= ones_add(sum_q, word);
                    have_hi <= 1'b0;
                end else begin
                    hi_q    <= in_data;
                    have_hi <= 1'b1;
                end
            end else if (out_take) begin
                out_v <= 1'b0;
                out_q <= '0;
            end
        end
    end
endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
    input  logic [BYTE_W-1:0]     in_data,
    input  logic                  in_last,
    output logic                  out_valid,
    input  logic                  out_ready,
    output logic [2*BYTE_W-1:0]  out_checksum
);
    localparam int W = 2 * BYTE_W;

    logic              have_hi;
    logic [BYTE_W-1:0] hi_q;
    logic [W-1:0]      sum_q;
    logic              out_v;
    logic [W-1:0]      out_q;

    // One's-complement add of two W-bit words with end-around carry.
    function automatic logic [W-1:0] ones_add(input logic [W-1:0] a,
                                              input logic [W-1:0] b);
        logic [W:0]   t;
        logic [W-1:0] r;
        begin
            t = {1'b0, a} + {1'b0, b};
            r = t[W-1:0] + {{(W-1){1'b0}}, t[W]};
            ones_add = r;
        end
    endfunction

    logic              acc;
    logic [W-1:0]      word;
    logic [W-1:0]      total;
    logic              out_take;

    assign in_ready  = !rst && (!in_last || !out_valid || out_ready);
    assign acc       = in_valid && in_ready;
    assign out_take  = out_v && out_ready;

    // Word formed from the current byte (and held upper byte if present).
    assign word  = have_hi ? {hi_q, in_data} : {in_data, {BYTE_W{1'b0}}};
    assign total = ones_add(sum_q, word);

    assign out_valid    = out_v;
    assign out_checksum = out_v ? out_q : '0;

    always_ff @(posedge clk) begin
        if (rst) begin
            have_hi <= 1'b0;
            hi_q    <= '0;
            sum_q   <= '0;
            out_v   <= 1'b0;
            out_q   <= '0;
        end else begin
            // Input path: accumulate bytes / words, finish packets.
            if (acc) begin
                if (in_last) begin
                    sum_q   <= '0;
                    have_hi <= 1'b0;
                end else if (have_hi) begin
                    sum_q   <= ones_add(sum_q, word);
                    have_hi <= 1'b0;
                end else begin
                    hi_q    <= in_data;
                    have_hi <= 1'b1;
                end
            end

            // Output slot path: independent of input path.
            if (acc && in_last) begin
                out_v <= 1'b1;
                out_q <= ~total;
            end else if (out_take) begin
                out_v <= 1'b0;
                out_q <= '0;
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int FW = 4 + PAYLOAD_W;

    // Output slot state
    logic [4:0]    sv;            // slot valid
    logic [FW-1:0] sf [5];        // slot flit
    logic [2:0]    sr [5];        // slot source index
    logic [2:0]    cur [5];       // arbitration cursor

    // Combinational helpers
    logic [2:0]    rt_arr [5];    // requested output per input
    logic [4:0]    want [5];      // want[o][j]
    logic [4:0]    xfer;
    logic [4:0]    avail;
    logic [2:0]    ceff [5];
    logic [4:0]    sel_v;
    logic [2:0]    sel_idx [5];
    logic [4:0]    inr;
    logic          found;
    integer        j;
    integer        o;
    integer        k;
    integer        idx;

    function automatic logic [2:0] route_fn(input logic [1:0] dx, input logic [1:0] dy);
        logic [2:0] r;
        if (dx > X)       r = 3'd2; // E
        else if (dx < X)  r = 3'd3; // W
        else if (dy > Y)  r = 3'd0; // N
        else if (dy < Y)  r = 3'd1; // S
        else              r = 3'd4; // L
        return r;
    endfunction

    function automatic logic [2:0] nxt(input logic [2:0] s);
        logic [2:0] r;
        if (s == 3'd4) r = 3'd0;
        else           r = s + 3'd1;
        return r;
    endfunction

    always_comb begin
        // Route computation per input lane
        for (j = 0; j < 5; j++) begin
            rt_arr[j] = route_fn(in_flit[j*FW + FW - 1 -: 2], in_flit[j*FW + FW - 3 -: 2]);
        end

        // Request matrix
        for (o = 0; o < 5; o++) begin
            for (j = 0; j < 5; j++) begin
                want[o][j] = in_valid[j] && (rt_arr[j] == 3'(o));
            end
        end

        // Per-output arbitration
        inr = '0;
        for (o = 0; o < 5; o++) begin
            xfer[o]  = sv[o] && out_ready[o];
            avail[o] = !sv[o] || out_ready[o];
            ceff[o]  = xfer[o] ? nxt(sr[o]) : cur[o];
            found    = 1'b0;
            sel_idx[o] = 3'd0;
            for (k = 0; k < 5; k++) begin
                idx = (int'(ceff[o]) + k) % 5;
                if (!found && want[o][idx]) begin
                    found = 1'b1;
                    sel_idx[o] = 3'(idx);
                end
            end
            sel_v[o] = avail[o] && found;
            if (sel_v[o]) inr[sel_idx[o]] = 1'b1;
        end

        in_ready  = inr & {5{!rst}};
        out_valid = sv;
        for (o = 0; o < 5; o++) begin
            out_flit[o*FW +: FW] = sv[o] ? sf[o] : '0;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sv <= '0;
            for (o = 0; o < 5; o++) begin
                cur[o] <= 3'd0;
            end
        end else begin
            for (o = 0; o < 5; o++) begin
                if (sel_v[o]) begin
                    sv[o] <= 1'b1;
                    sf[o] <= in_flit[int'(sel_idx[o])*FW +: FW];
                    sr[o] <= sel_idx[o];
                end else if (xfer[o]) begin
                    sv[o] <= 1'b0;
                end
                cur[o] <= ceff[o];
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int FW = 4 + PAYLOAD_W;

    // Registered state (packed, 3 bits per output where applicable)
    logic [4:0]          sv;      // slot valid
    logic [5*FW-1:0]     sf;      // slot flits
    logic [14:0]         sr;      // slot source index
    logic [14:0]         cur;     // arbitration cursor

    // Combinational signals
    logic [14:0]         rt_p;    // requested output per input
    logic [4:0]          xfer;
    logic [4:0]          avail;
    logic [14:0]         ceff_p;
    logic [4:0]          sel_v;
    logic [14:0]         sel_idx_p;
    logic [4:0]          inr;

    function automatic logic [2:0] route_fn(input logic [1:0] dx, input logic [1:0] dy);
        logic [2:0] r;
        if (dx > X)       r = 3'd2; // E
        else if (dx < X)  r = 3'd3; // W
        else if (dy > Y)  r = 3'd0; // N
        else if (dy < Y)  r = 3'd1; // S
        else              r = 3'd4; // L
        return r;
    endfunction

    function automatic logic [2:0] nxt(input logic [2:0] s);
        logic [2:0] r;
        if (s == 3'd4) r = 3'd0;
        else           r = s + 3'd1;
        return r;
    endfunction

    genvar j;
    generate
        for (j = 0; j < 5; j++) begin : g_rt
            assign rt_p[3*j +: 3] = route_fn(in_flit[j*FW + FW - 1 -: 2],
                                             in_flit[j*FW + FW - 3 -: 2]);
        end
    endgenerate

    genvar o;
    generate
        for (o = 0; o < 5; o++) begin : g_out
            logic [4:0] want_c;
            logic [2:0] ceff_c;
            logic [2:0] idx_c;
            logic       found_c;
            logic       xf;
            integer     jj;
            integer     kk;
            integer     tmp;

            assign xf          = sv[o] && out_ready[o];
            assign xfer[o]     = xf;
            assign avail[o]    = !sv[o] || out_ready[o];
            assign ceff_c      = xf ? nxt(sr[3*o +: 3]) : cur[3*o +: 3];
            assign ceff_p[3*o +: 3]   = ceff_c;
            assign sel_v[o]           = avail[o] && found_c;
            assign sel_idx_p[3*o +: 3] = idx_c;

            always_comb begin
                for (jj = 0; jj < 5; jj++) begin
                    want_c[jj] = in_valid[jj] && (rt_p[3*jj +: 3] == 3'(o));
                end
                found_c = 1'b0;
                idx_c   = 3'd0;
                for (kk = 0; kk < 5; kk++) begin
                    tmp = (int'(ceff_c) + kk) % 5;
                    if (!found_c && want_c[tmp]) begin
                        found_c = 1'b1;
                        idx_c   = 3'(tmp);
                    end
                end
            end
        end
    endgenerate

    always_comb begin
        inr = '0;
        for (int q = 0; q < 5; q++) begin
            if (sel_v[q]) inr[sel_idx_p[3*q +: 3]] = 1'b1;
        end
    end

    assign in_ready  = inr & {5{!rst}};
    assign out_valid = sv;

    genvar p;
    generate
        for (p = 0; p < 5; p++) begin : g_oflit
            assign out_flit[p*FW +: FW] = sv[p] ? sf[p*FW +: FW] : '0;
        end
    endgenerate

    always_ff @(posedge clk) begin
        if (rst) begin
            sv  <= '0;
            cur <= '0;
        end else begin
            for (int q = 0; q < 5; q++) begin
                if (sel_v[q]) begin
                    sv[q] <= 1'b1;
                    sf[q*FW +: FW] <= in_flit[int'(sel_idx_p[3*q +: 3])*FW +: FW];
                    sr[3*q +: 3]   <= sel_idx_p[3*q +: 3];
                end else if (xfer[q]) begin
                    sv[q] <= 1'b0;
                end
                cur[3*q +: 3] <= ceff_p[3*q +: 3];
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int FW = 4 + PAYLOAD_W;

    // Registered state
    logic [4:0]      sv;        // slot valid
    logic [5*FW-1:0] sf;        // slot flits
    logic [14:0]     sr;        // slot source index (3 bits per output)
    logic [14:0]     cur;       // arbitration cursor (3 bits per output)

    // Combinational signals
    logic [14:0]     rt_p;      // requested output per input (3 bits each)
    logic [14:0]     ceff_p;    // effective cursor per output
    logic [14:0]     sel_idx_p; // chosen input per output
    logic [4:0]      sel_v;     // output selects a new flit
    logic [4:0]      xfer;      // output transfer this edge
    logic [4:0]      inr;       // input ready (before reset gating)

    // Loop and temporary variables
    integer          i;
    integer          o;
    integer          k;
    integer          tmp;
    integer          ce;
    integer          p;
    integer          q;
    logic            found;
    logic [2:0]      idxv;
    logic [2:0]      ceffv;
    logic            xf;
    logic            av;
    logic [2:0]      cs;
    logic [1:0]      dx;
    logic [1:0]      dy;
    logic [2:0]      rv;

    always_comb begin
        // Route computation
        for (i = 0; i < 5; i++) begin
            dx = in_flit[i*FW + FW - 1 -: 2];
            dy = in_flit[i*FW + FW - 3 -: 2];
            if (dx > X)       rv = 3'd2; // E
            else if (dx < X)  rv = 3'd3; // W
            else if (dy > Y)  rv = 3'd0; // N
            else if (dy < Y)  rv = 3'd1; // S
            else              rv = 3'd4; // L
            rt_p[3*i +: 3] = rv;
        end

        // Per-output arbitration
        inr    = '0;
        xfer   = '0;
        sel_v  = '0;
        sel_idx_p = '0;
        ceff_p = '0;
        for (o = 0; o < 5; o++) begin
            xf = sv[o] && out_ready[o];
            av = (!sv[o]) || out_ready[o];
            xfer[o] = xf;
            if (xf) begin
                cs = sr[3*o +: 3];
                if (cs == 3'd4) ceffv = 3'd0;
                else            ceffv = cs + 3'd1;
            end else begin
                ceffv = cur[3*o +: 3];
            end
            ceff_p[3*o +: 3] = ceffv;

            found = 1'b0;
            idxv  = 3'd0;
            ce    = int'(ceffv);
            for (k = 0; k < 5; k++) begin
                tmp = (ce + k) % 5;
                if (!found && in_valid[tmp] && (rt_p[3*tmp +: 3] == o)) begin
                    found = 1'b1;
                    idxv  = tmp;
                end
            end

            sel_v[o] = av && found;
            sel_idx_p[3*o +: 3] = idxv;
            if (sel_v[o]) inr[idxv] = 1'b1;
        end

        in_ready  = inr & {5{!rst}};
        out_valid = sv;

        for (p = 0; p < 5; p++) begin
            out_flit[p*FW +: FW] = sv[p] ? sf[p*FW +: FW] : '0;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sv  <= '0;
            cur <= '0;
        end else begin
            for (q = 0; q < 5; q++) begin
                if (sel_v[q]) begin
                    sv[q] <= 1'b1;
                    sf[q*FW +: FW] <= in_flit[sel_idx_p[3*q +: 3] * FW +: FW];
                    sr[3*q +: 3]   <= sel_idx_p[3*q +: 3];
                end else if (xfer[q]) begin
                    sv[q] <= 1'b0;
                end
                cur[3*q +: 3] <= ceff_p[3*q +: 3];
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Registered state
    logic [4:0]   sv_q;
    logic [F-1:0] sf_q [5];
    logic [2:0]   ss_q [5];
    logic [2:0]   cur_q [5];

    // Next state
    logic [4:0]   sv_d;
    logic [F-1:0] sf_d [5];
    logic [2:0]   ss_d [5];
    logic [2:0]   cur_d [5];

    // Combinational helpers
    logic [2:0]   req [5];
    logic [4:0]   avail;
    logic [4:0]   xfer;
    logic [4:0]   wf;
    logic [2:0]   win [5];
    logic [4:0]   inr;

    integer i, o, k, j, st;
    logic [1:0] dx, dy;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        // Routing per input lane
        for (i = 0; i < 5; i = i + 1) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)        req[i] = 3'd2; // E
            else if (dx < X)   req[i] = 3'd3; // W
            else if (dy > Y)   req[i] = 3'd0; // N
            else if (dy < Y)   req[i] = 3'd1; // S
            else               req[i] = 3'd4; // L
        end

        // Per-output availability, transfer, and arbitration
        for (o = 0; o < 5; o = o + 1) begin
            avail[o] = !sv_q[o] || out_ready[o];
            xfer[o]  = sv_q[o] && out_ready[o];
            st = xfer[o] ? int'(succ(ss_q[o])) : int'(cur_q[o]);
            wf[o]  = 1'b0;
            win[o] = 3'd0;
            for (k = 0; k < 5; k = k + 1) begin
                j = (st + k) % 5;
                if (!wf[o] && in_valid[j] && (req[j] == o[2:0])) begin
                    wf[o]  = 1'b1;
                    win[o] = j[2:0];
                end
            end
        end

        // Input ready
        inr = 5'b0;
        for (o = 0; o < 5; o = o + 1) begin
            if (!rst && avail[o] && wf[o])
                inr[win[o]] = 1'b1;
        end
        in_ready = inr;

        // Next state
        for (o = 0; o < 5; o = o + 1) begin
            sv_d[o] = sv_q[o];
            sf_d[o] = sf_q[o];
            ss_d[o] = ss_q[o];
            cur_d[o] = cur_q[o];
            if (avail[o] && wf[o]) begin
                sv_d[o] = 1'b1;
                sf_d[o] = in_flit[win[o]*F +: F];
                ss_d[o] = win[o];
            end else if (xfer[o]) begin
                sv_d[o] = 1'b0;
            end
            if (xfer[o])
                cur_d[o] = succ(ss_q[o]);
        end

        // Outputs
        out_valid = sv_q;
        for (o = 0; o < 5; o = o + 1) begin
            out_flit[o*F +: F] = sv_q[o] ? sf_q[o] : {F{1'b0}};
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sv_q <= 5'b0;
            for (o = 0; o < 5; o = o + 1) begin
                cur_q[o] <= 3'd0;
                ss_q[o]  <= 3'd0;
                sf_q[o]  <= {F{1'b0}};
            end
        end else begin
            sv_q <= sv_d;
            for (o = 0; o < 5; o = o + 1) begin
                sf_q[o]  <= sf_d[o];
                ss_q[o]  <= ss_d[o];
                cur_q[o] <= cur_d[o];
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Registered state (packed; lane o at [o*W +: W])
    logic [4:0]       sv_q, sv_d;
    logic [5*F-1:0]   sf_q, sf_d;
    logic [14:0]      ss_q, ss_d;   // 3 bits per output: source index
    logic [14:0]      cur_q, cur_d; // 3 bits per output: cursor

    // Combinational
    logic [14:0]      req;          // 3 bits per input: requested output
    logic [4:0]       avail;
    logic [4:0]       xfer;
    logic [4:0]       wf;
    logic [14:0]      win;          // 3 bits per output: winning input
    logic [4:0]       inr;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    // Returns {found, index} for output oi, scanning cyclically from st.
    function automatic logic [3:0] arb(input logic [4:0] vld,
                                       input logic [14:0] reqs,
                                       input logic [2:0] st,
                                       input logic [2:0] oi);
        logic [3:0] r;
        integer k;
        integer j;
        integer s;
        r = 4'd0;
        s = int'(st);
        for (k = 0; k < 5; k = k + 1) begin
            j = (s + k) % 5;
            if (!r[3] && vld[j] && (reqs[j*3 +: 3] == oi))
                r = {1'b1, 3'(j)};
        end
        return r;
    endfunction

    integer i, o, w;
    logic [1:0] dx, dy;
    logic [3:0] r;
    logic [2:0] st;

    always_comb begin
        // Routing
        req = 15'd0;
        for (i = 0; i < 5; i = i + 1) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)        req[i*3 +: 3] = 3'd2; // E
            else if (dx < X)   req[i*3 +: 3] = 3'd3; // W
            else if (dy > Y)   req[i*3 +: 3] = 3'd0; // N
            else if (dy < Y)   req[i*3 +: 3] = 3'd1; // S
            else               req[i*3 +: 3] = 3'd4; // L
        end

        // Availability, transfer, arbitration
        for (o = 0; o < 5; o = o + 1) begin
            avail[o] = !sv_q[o] || out_ready[o];
            xfer[o]  = sv_q[o] && out_ready[o];
            if (xfer[o])
                st = succ(ss_q[o*3 +: 3]);
            else
                st = cur_q[o*3 +: 3];
            r = arb(in_valid, req, st, 3'(o));
            wf[o] = r[3];
            win[o*3 +: 3] = r[2:0];
        end

        // Input ready
        inr = 5'd0;
        for (o = 0; o < 5; o = o + 1) begin
            if (!rst && avail[o] && wf[o]) begin
                w = int'(win[o*3 +: 3]);
                inr[w] = 1'b1;
            end
        end
        in_ready = inr;

        // Next state
        sv_d  = sv_q;
        sf_d  = sf_q;
        ss_d  = ss_q;
        cur_d = cur_q;
        for (o = 0; o < 5; o = o + 1) begin
            if (avail[o] && wf[o]) begin
                w = int'(win[o*3 +: 3]);
                sv_d[o] = 1'b1;
                sf_d[o*F +: F] = in_flit[w*F +: F];
                ss_d[o*3 +: 3] = win[o*3 +: 3];
            end else if (xfer[o]) begin
                sv_d[o] = 1'b0;
            end
            if (xfer[o])
                cur_d[o*3 +: 3] = succ(ss_q[o*3 +: 3]);
        end

        // Outputs
        out_valid = sv_q;
        for (o = 0; o < 5; o = o + 1) begin
            out_flit[o*F +: F] = sv_q[o] ? sf_q[o*F +: F] : {F{1'b0}};
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sv_q  <= 5'd0;
            cur_q <= 15'd0;
        end else begin
            sv_q  <= sv_d;
            cur_q <= cur_d;
        end
        sf_q <= sf_d;
        ss_q <= ss_d;
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Registered state
    logic [4:0]     sv_q, sv_d;
    logic [5*F-1:0] sf_q, sf_d;
    logic [14:0]    ss_q, ss_d;    // 3 bits per output: source index
    logic [14:0]    cur_q, cur_d;  // 3 bits per output: cursor

    // Combinational
    logic [24:0]    dsel;          // 5 bits per input: one-hot requested output
    logic [24:0]    G;             // 5 bits per output: one-hot granted input
    logic [4:0]     avail;
    logic [4:0]     xfer;
    logic [4:0]     rv;
    logic [4:0]     gg;
    logic [4:0]     ir;
    logic [F-1:0]   tmp;
    logic [2:0]     st;
    logic [2:0]     enc;
    logic [1:0]     dx, dy;
    integer         i, o;

    function automatic logic [2:0] succ(input logic [2:0] s);
        logic [2:0] r;
        if (s == 3'd4) r = 3'd0;
        else           r = s + 3'd1;
        return r;
    endfunction

    // Cyclic fixed-priority pick starting at s; returns one-hot grant.
    function automatic logic [4:0] pick(input logic [4:0] R, input logic [2:0] s);
        logic [9:0] dr;
        logic [4:0] rot;
        logic [4:0] low;
        logic [9:0] g10;
        logic [4:0] gb;
        dr  = {R, R};
        rot = dr[s +: 5];
        low = rot & (~rot + 5'd1);
        g10 = {5'd0, low} << s;
        gb  = g10[4:0] | g10[9:5];
        return gb;
    endfunction

    always_comb begin
        // Routing: one-hot destination per input
        dsel = 25'd0;
        for (i = 0; i < 5; i = i + 1) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)        dsel[i*5 +: 5] = 5'b00100; // E
            else if (dx < X)   dsel[i*5 +: 5] = 5'b01000; // W
            else if (dy > Y)   dsel[i*5 +: 5] = 5'b00001; // N
            else if (dy < Y)   dsel[i*5 +: 5] = 5'b00010; // S
            else               dsel[i*5 +: 5] = 5'b10000; // L
        end

        // Per-output availability, transfer, arbitration
        G = 25'd0;
        for (o = 0; o < 5; o = o + 1) begin
            avail[o] = !sv_q[o] || out_ready[o];
            xfer[o]  = sv_q[o] && out_ready[o];
            rv = 5'd0;
            for (i = 0; i < 5; i = i + 1) begin
                rv[i] = in_valid[i] & dsel[i*5 + o];
            end
            st = xfer[o] ? succ(ss_q[o*3 +: 3]) : cur_q[o*3 +: 3];
            gg = pick(rv, st) & {5{avail[o] & !rst}};
            G[o*5 +: 5] = gg;
        end

        // Input ready
        ir = 5'd0;
        for (o = 0; o < 5; o = o + 1) begin
            ir = ir | G[o*5 +: 5];
        end
        in_ready = ir;

        // Next state
        sv_d  = sv_q;
        sf_d  = sf_q;
        ss_d  = ss_q;
        cur_d = cur_q;
        for (o = 0; o < 5; o = o + 1) begin
            tmp = {F{1'b0}};
            enc = 3'd0;
            for (i = 0; i < 5; i = i + 1) begin
                if (G[o*5 + i]) begin
                    tmp = tmp | in_flit[i*F +: F];
                    enc = i[2:0];
                end
            end
            if (|G[o*5 +: 5]) begin
                sv_d[o]          = 1'b1;
                sf_d[o*F +: F]   = tmp;
                ss_d[o*3 +: 3]   = enc;
            end else if (xfer[o]) begin
                sv_d[o] = 1'b0;
            end
            if (xfer[o])
                cur_d[o*3 +: 3] = succ(ss_q[o*3 +: 3]);
        end

        // Outputs
        out_valid = sv_q;
        for (o = 0; o < 5; o = o + 1) begin
            out_flit[o*F +: F] = sv_q[o] ? sf_q[o*F +: F] : {F{1'b0}};
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sv_q  <= 5'd0;
            cur_q <= 15'd0;
        end else begin
            sv_q  <= sv_d;
            cur_q <= cur_d;
        end
        sf_q <= sf_d;
        ss_q <= ss_d;
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Source / output indices: N=0, S=1, E=2, W=3, L=4
    logic [F-1:0] slot_flit [0:4];
    logic [4:0]   slot_valid;
    logic [2:0]   slot_src  [0:4];
    logic [2:0]   cur       [0:4];

    // Routing request per input
    logic [2:0] rq [0:4];

    // Effective cursor (advanced by a retiring flit on this edge)
    logic [2:0] cur_eff [0:4];

    // Per-output winner
    logic       wv [0:4];
    logic [2:0] wi [0:4];
    logic       acc [0:4];

    logic [4:0] avail;

    // Routing computation
    always_comb begin
        logic [1:0] dx;
        logic [1:0] dy;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)
                rq[i] = 3'd2;      // E
            else if (dx < X)
                rq[i] = 3'd3;      // W
            else if (dy > Y)
                rq[i] = 3'd0;      // N
            else if (dy < Y)
                rq[i] = 3'd1;      // S
            else
                rq[i] = 3'd4;      // L
        end
    end

    // Availability and effective cursors
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            avail[o] = !slot_valid[o] || out_ready[o];
            if (slot_valid[o] && out_ready[o]) begin
                cur_eff[o] = (slot_src[o] == 3'd4) ? 3'd0 : slot_src[o] + 3'd1;
            end else begin
                cur_eff[o] = cur[o];
            end
        end
    end

    // Cyclic arbitration per output
    always_comb begin
        int t;
        for (int o = 0; o < 5; o++) begin
            wv[o] = 1'b0;
            wi[o] = 3'd0;
            for (int k = 0; k < 5; k++) begin
                t = int'(cur_eff[o]) + k;
                if (t >= 5) t = t - 5;
                if (!wv[o] && in_valid[t] && (int'(rq[t]) == o)) begin
                    wv[o] = 1'b1;
                    wi[o] = 3'(t);
                end
            end
            acc[o] = avail[o] && wv[o];
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            in_ready[i] = in_valid[i] && acc[rq[i]] && (wi[rq[i]] == 3'(i));
        end
    end

    // Outputs
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_valid[o] = slot_valid[o];
            out_flit[o*F +: F] = slot_valid[o] ? slot_flit[o] : '0;
        end
    end

    // State update
    always_ff @(posedge clk) begin
        if (rst) begin
            slot_valid <= '0;
            for (int o = 0; o < 5; o++) begin
                slot_flit[o] <= '0;
                slot_src[o]  <= 3'd0;
                cur[o]       <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur[o] <= cur_eff[o];
                if (acc[o]) begin
                    slot_valid[o] <= 1'b1;
                    slot_flit[o]  <= in_flit[int'(wi[o])*F +: F];
                    slot_src[o]   <= wi[o];
                end else if (out_ready[o]) begin
                    slot_valid[o] <= 1'b0;
                end
            end
        end
    end

endmodule

